,"brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7477372","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7254086","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7269597","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR6392001","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7477331","brand":"SVR","cats":["protecao-solar","cuidados-com-a-pele"]},{"sku":"SVR7477349","brand":"SVR","cats":["protecao-solar","cuidados-com-a-pele"]},{"sku":"SVR6291286","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7111005","brand":"SVR","cats":["protecao-solar","cuidados-com-a-pele"]},{"sku":"SVR7260372","brand":"SVR","cats":["protecao-solar","cuidados-com-a-pele"]},{"sku":"SVR7477380","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR6050674","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7111013","brand":"SVR","cats":["protecao-solar","cuidados-com-a-pele"]},{"sku":"SVR6287896","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR6287888","brand":"SVR","cats":["protecao-solar"]},{"sku":"SVR7085530","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele","higiene-pessoal"]},{"sku":"SVR7239434","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"SVR6963546","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"SVR7087569","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele","higiene-pessoal"]},{"sku":"SVR6393173","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele","higiene-pessoal"]},{"sku":"SVR7406207","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"SVR6503524","brand":"SVR","cats":["maquilhagem","cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"LOR7576207","brand":"Vichy","cats":["cuidados-com-a-pele"]},{"sku":"LOR7576199","brand":"Vichy","cats":["cuidados-com-a-pele"]},{"sku":"LOR7576215","brand":"Vichy","cats":["cuidados-com-a-pele"]},{"sku":"LOR7576223","brand":"Vichy","cats":["cuidados-com-a-pele"]},{"sku":"SVR7112698","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"SVR6959460","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"SVR6977413","brand":"SVR","cats":["cuidados-do-corpo","cuidados-com-a-pele"]},{"sku":"LAZ6618900","brand":"Mednord","cats":["cabelo"]},{"sku":"LAZ6618892","brand":"Mednord","cats":["cabelo"]},{"sku":"LAZ6618884","brand":"Mednord","cats":["cabelo"]},{"sku":"LAZ6618868","brand":"Mednord","cats":["cabelo"]},{"sku":"LAZ6618850","brand":"Mednord","cats":["cabelo"]},{"sku":"LAZ7085191","brand":"Mednord","cats":["cabelo"]},{"sku":"LAZ6618843","brand":"Mednord","cats":["cabelo"]},{"sku":"LOR7563296","brand":"Opuscare","cats":["protecao-solar"]},{"sku":"LOR7563304","brand":"Opuscare","cats":["protecao-solar"]},{"sku":"LOR7563288","brand":"Opuscare","cats":["protecao-solar"]},{"sku":"LOR7304808","brand":"Opuscare","cats":["protecao-solar"]},{"sku":"LOR7563346","brand":"Opuscare","cats":["protecao-solar"]},{"sku":"LOR7563338","brand":"Opuscare","cats":["protecao-solar"]},{"sku":"BRA503","brand":"Hartmann","cats":["cabelo","higiene-pessoal"]}],"brands":["Lazartigue","ATL","Mednord","Avène","Opuscare","Barral","Bayer","CeraVe","SVR","Noreva","Vichy","Essence","Eucerin","La Roche Posay","Segle","Hartmann"],"taxonomy":[{"slug":"cuidados-com-a-pele","name":"Cuidados com a Pele","sort":10},{"slug":"cuidados-do-corpo","name":"Cuidados do Corpo","sort":20},{"slug":"protecao-solar","name":"Proteção Solar","sort":30},{"slug":"cabelo","name":"Cabelo","sort":40},{"slug":"higiene-pessoal","name":"Higiene Pessoal","sort":50},{"slug":"maquilhagem","name":"Maquilhagem","sort":60},{"slug":"cosmetica","name":"Cosmética","sort":70}]}$json$::jsonb;
  prod jsonb;
  brand_name text;
  brand_slug text;
  brand_uuid uuid;
  cat_slug text;
  cat_uuid uuid;
  prod_uuid uuid;
  keep_skus text[];
  first_cat text;
BEGIN
  -- collect keep skus
  SELECT array_agg(p->>'sku') INTO keep_skus
  FROM jsonb_array_elements(payload->'products') p;

  -- upsert brands
  FOR brand_name IN SELECT DISTINCT p->>'brand' FROM jsonb_array_elements(payload->'products') p
  LOOP
    brand_slug := regexp_replace(
      lower(translate(brand_name, 'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ', 'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn')),
      '[^a-z0-9]+', '-', 'g'
    );
    brand_slug := trim(both '-' from brand_slug);
    IF brand_slug = '' THEN brand_slug := 'marca'; END IF;

    INSERT INTO brands (name, slug, active)
    VALUES (brand_name, brand_slug, true)
    ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, active = true;
  END LOOP;

  -- deactivate products not in keep list
  UPDATE products
  SET active = false, updated_at = now()
  WHERE active = true
    AND (sku IS NULL OR NOT (sku = ANY (keep_skus)));

  -- activate keep products that exist
  UPDATE products
  SET active = true, updated_at = now()
  WHERE sku = ANY (keep_skus);

  -- assign brand + categories
  FOR prod IN SELECT * FROM jsonb_array_elements(payload->'products')
  LOOP
    SELECT id INTO prod_uuid FROM products WHERE sku = prod->>'sku';
    IF prod_uuid IS NULL THEN
      CONTINUE;
    END IF;

    brand_name := prod->>'brand';
    SELECT id INTO brand_uuid FROM brands WHERE lower(name) = lower(brand_name) LIMIT 1;
    IF brand_uuid IS NOT NULL THEN
      UPDATE products SET brand_id = brand_uuid, updated_at = now() WHERE id = prod_uuid;
    END IF;

    DELETE FROM product_categories WHERE product_id = prod_uuid;

    first_cat := NULL;
    FOR cat_slug IN SELECT jsonb_array_elements_text(prod->'cats')
    LOOP
      SELECT id INTO cat_uuid FROM categories WHERE slug = cat_slug LIMIT 1;
      IF cat_uuid IS NOT NULL THEN
        INSERT INTO product_categories (product_id, category_id)
        VALUES (prod_uuid, cat_uuid)
        ON CONFLICT DO NOTHING;
        IF first_cat IS NULL THEN
          first_cat := cat_slug;
          UPDATE products SET category_id = cat_uuid, updated_at = now() WHERE id = prod_uuid;
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  -- deactivate unused categories (except taxonomy)
  UPDATE categories c
  SET active = false
  WHERE c.slug NOT IN (
    'cuidados-com-a-pele','cuidados-do-corpo','protecao-solar','cabelo','higiene-pessoal','maquilhagem','cosmetica'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM product_categories pc
    JOIN products p ON p.id = pc.product_id AND p.active = true
    WHERE pc.category_id = c.id
  );

  -- ensure taxonomy active
  UPDATE categories
  SET active = true
  WHERE slug IN (
    'cuidados-com-a-pele','cuidados-do-corpo','protecao-solar','cabelo','higiene-pessoal','maquilhagem','cosmetica'
  );

  -- deactivate unused brands
  UPDATE brands b
  SET active = false
  WHERE NOT EXISTS (
    SELECT 1 FROM products p WHERE p.brand_id = b.id AND p.active = true
  );

  UPDATE brands b
  SET active = true
  WHERE EXISTS (
    SELECT 1 FROM products p WHERE p.brand_id = b.id AND p.active = true
  );
END $$;
